contracts/Governance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Governance {
    struct Proposal {
        string description;
        bool executed;
        uint256 votesFor;
        uint256 votesAgainst;
    }
    Proposal[] public proposals;
    mapping(address => bool) public hasVoted;

    event ProposalCreated(uint256 id, string description);
    event ProposalExecuted(uint256 id);

    function createProposal(string memory desc) public {
        proposals.push(Proposal(desc, false, 0, 0));
        emit ProposalCreated(proposals.length - 1, desc);
    }

    function vote(uint256 id, bool support) public {
        require(!hasVoted[msg.sender], "Already voted");
        require(id < proposals.length, "Invalid proposal");
        hasVoted[msg.sender] = true;
        if (support) {
            proposals[id].votesFor++;
        } else {
            proposals[id].votesAgainst++;
        }
    }

    function executeProposal(uint256 id) public {
        require(id < proposals.length, "Invalid proposal");
        require(!proposals[id].executed, "Already executed");
        proposals[id].executed = true;
        emit ProposalExecuted(id);
    }
}

contracts/Marketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Marketplace {
    struct Item {
        string name;
        uint256 price;
        address seller;
        bool sold;
    }
    Item[] public items;
    event ItemListed(uint256 id, string name, uint256 price);
    event ItemSold(uint256 id, address buyer);

    function listItem(string memory name, uint256 price) public {
        items.push(Item(name, price, msg.sender, false));
        emit ItemListed(items.length - 1, name, price);
    }

    function buyItem(uint256 id) public payable {
        require(id < items.length, "Invalid item");
        Item storage item = items[id];
        require(!item.sold, "Already sold");
        require(msg.value == item.price, "Incorrect price");
        item.sold = true;
        payable(item.seller).transfer(msg.value);
        emit ItemSold(id, msg.sender);
    }
}

contracts/Reentrancy.sol.content:
// Reentrancy.sol
pragma solidity ^0.8.0;

contract Reentrancy {
    mapping(address => uint256) public balances;
    bool private locked;

    modifier noReentrancy() {
        require(!locked, "No reentrancy");
        locked = true;
        _;
        locked = false;
    }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw() external noReentrancy {
        uint256 amount = balances[msg.sender];
        require(amount > 0, "No balance to withdraw");

        // Critical fix - update balance BEFORE external call
        balances[msg.sender] = 0;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
    }
}

contracts/Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Token {
    string public name = "TestToken";
    string public symbol = "TTK";
    uint8 public decimals = 18;
    uint256 public totalSupply = 1000000 * 10**18;
    mapping(address => uint256) public balanceOf;

    event Transfer(address indexed from, address indexed to, uint256 value);

    constructor() {
        balanceOf[msg.sender] = totalSupply;
    }

    function transfer(address to, uint256 value) public returns (bool) {
        require(balanceOf[msg.sender] >= value, "Not enough tokens");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }
}

